def descent_step(w, grad, lr):
    """Return the weight after one gradient-descent step."""
    return w + lr * grad

tests_py:
def test_known_value():
    assert solution.descent_step(3.0, 6.0, 0.1) == 2.4

def test_direction():
    assert solution.descent_step(1.0, 2.0, 0.5) < 1.0

def test_zero_grad():
    assert solution.descent_step(5.0, 0.0, 0.9) == 5.0

def test_negative_grad():
    assert abs(solution.descent_step(1.0, -2.0, 0.5) - 2.0) < 1e-12

def test_lr_scaling():
    assert abs(solution.descent_step(0.0, 1.0, 0.25) + 0.25) < 1e-12

def test_returns_float():
    assert isinstance(solution.descent_step(1, 1, 0.5), float)
